const express = require('express');
require('reflect-metadata');
const { plainToInstance } = require('class-transformer');
const { validateOrReject, IsString, IsEnum, IsNumber, Min, Matches } = require('class-validator');
const { PurchaseOrder } = require('../models/sequelizePurchaseOrder');

const app = express();
app.use(express.json());

enum OrderDecision {
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

class ApprovePurchaseOrderDto {
  @IsString()
  @Matches(/^PO-\d{6}$/)
  poNumber;

  @IsEnum(OrderDecision)
  decision;

  @IsNumber()
  @Min(0)
  approvedBudget;
}

const dtoMiddleware = (targetClass) => async (req, res, next) => {
  const instance = plainToInstance(targetClass, req.body);
  try {
    await validateOrReject(instance);
    req.dto = instance;
    next();
  } catch (err) {
    res.status(400).json({ error: 'Invalid DTO payload' });
  }
};

app.post('/api/procurement/orders/decision', dtoMiddleware(ApprovePurchaseOrderDto), async (req, res) => {
  if (!req.user || !req.user.companyId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { poNumber, decision, approvedBudget } = req.dto;

  // Scope purchase order query to caller's companyId
  const po = await PurchaseOrder.findOne({
    where: { poNumber, buyerCompanyId: req.user.companyId }
  });

  if (!po) {
    return res.status(404).json({ error: 'Purchase order not found or unauthorized' });
  }

  po.status = decision;
  po.authorizedAmount = approvedBudget;
  await po.save();

  res.json({ success: true, poNumber, status: po.status });
});

app.listen(7002);
